def parse(tree):
    val, left, right = [tree[0]], [-1], [-1]
    i, u = 1, 0
    while u < len(val) and i < len(tree):
        for kids in (left, right):
            if i < len(tree):
                x = tree[i]
                i += 1
                if x != -1:
                    kids[u] = len(val)
                    val.append(x)
                    left.append(-1)
                    right.append(-1)
        u += 1
    return val, left, right


from bisect import bisect_left


def kClosestInBst(tree, target, k):
    val, left, right = parse(tree)
    v, stack, u = [], [], 0
    while stack or u != -1:
        while u != -1:
            stack.append(u)
            u = left[u]
        u = stack.pop()
        v.append(val[u])
        u = right[u]
    hi = bisect_left(v, target)
    lo = hi - 1
    for _ in range(k):
        if lo < 0:
            hi += 1
        elif hi >= len(v):
            lo -= 1
        elif (target - v[lo], v[lo]) <= (v[hi] - target, v[hi]):
            lo -= 1
        else:
            hi += 1
    return v[lo + 1:hi]
